import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 seed, uint96 blockNum) public {
        // Restrict domain to ensure pot starts at 0
        vm.assume(blockNum > 0);
        vm.roll(blockNum);
        vm.warp(seed);

        // Record pot before play
        uint256 potBefore = c.pot();

        // Deal ether to a fresh player and play
        address player = address(uint160(uint256(keccak256(abi.encode(seed, blockNum)))));
        vm.deal(player, 10);
        vm.prank(player);
        c.play{value: 10}();

        // Get pot after play
        uint256 potAfter = c.pot();

        // If the play was losing (pot did not reset to 0), pot must have increased by 10.
        // If potAfter == 0, the play was winning and pot was reset, so no assertion needed.
        // Reference: pot increases by 10 on every play; on losing play pot remains > 0.
        // Bug: on losing play pot never increases, so after a losing play, potAfter == potBefore.
        // Rule: if potAfter != 0, then potAfter == potBefore + 10.
        assertTrue(potAfter == 0 || potAfter == potBefore + 10);
    }
}

