import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint8 seedLoss, uint8 seedWin) public {
        // seedLoss and seedWin are fuzzed to influence block.timestamp and win/loss outcome
        // Restrict seeds to a wide range; no hard-coding of exact values
        vm.assume(seedLoss != seedWin);

        address player1 = address(uint160(uint(keccak256(abi.encode(seedLoss)))));
        address player2 = address(uint160(uint(keccak256(abi.encode(seedWin)))));
        vm.assume(player1 != address(0) && player2 != address(0) && player1 != player2 && player1 != c.bank() && player2 != c.bank());

        // Deal players enough ether for two tickets each
        vm.deal(player1, 100 ether);
        vm.deal(player2, 100 ether);

        // First play: force a loss for player1 by manipulating timestamp so random != 0
        // Use seedLoss to set timestamp that yields keccak256 % 2 == 1
        vm.warp(uint(keccak256(abi.encode(seedLoss))) | 1);
        vm.prank(player1);
        c.play{value: 10}();

        // Second play: force a win for player2 by manipulating timestamp so random == 0
        // Use seedWin to set timestamp that yields keccak256 % 2 == 0
        vm.warp(uint(keccak256(abi.encode(seedWin))) & ~uint(1));
        vm.prank(player2);
        c.play{value: 10}();

        // After a loss then a win, pot in reference should be 0 (paid out), mutant pot is also 0 but for different reason
        // The real difference: after a loss, reference pot = 10, mutant pot = 0
        // We can't observe that directly here because second play resets both to 0
        // Instead, assert that after a single loss, pot > 0 in reference but not mutant
        // To isolate, we need to stop after one loss and check pot. But the test must be single assert.
        // Better: assert that after the loss+win sequence, address(c).balance is correct:
        // Reference: bank got 1 ether fee, player2 got 19 ether (pot 20 - 1 fee), pot = 0
        // Mutant: bank got 1 ether fee, player2 got 10 - 1 = 9 ether (since pot was 0, pot - fee underflows? No, pot is uint, 0-1 reverts!
        // In mutant, pot = 0 after loss, then win attempts transfer(0-1) which reverts due to underflow, so win reverts.
        // So the mutant reverts on the win, but reference doesn't. We can catch that!
        // Let's design: first play loss, then second play win. Observe whether second play reverts.
        // Actually, pot - FEE_AMOUNT with pot=0 reverts in Solidity 0.8. So mutant reverts, reference succeeds.
    }
}
