pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint8 times) public {
        // times controls how many play() calls we make; bound to 1..20 to stay reasonable
        times = uint8(bound(times, 1, 20));
        // start bank with zero balance (EVM default)
        uint256 initialContractBalance = 0;
        uint256 initialPot = c.pot();
        uint256 initialBankBalance = c.bank().balance;
        // invariant: after every call, pot <= total paid in - total paid to bank (i.e., pot never pays out jackpot)
        uint256 totalPaidIn = 0;
        uint256 totalBankFees = 0;
        for (uint256 i = 0; i < times; i++) {
            uint256 msgValue = 10; // TICKET_AMOUNT
            address player = address(uint160(uint256(keccak256(abi.encode(i, block.timestamp, msg.sender)))));
            vm.deal(player, msgValue);
            vm.prank(player);
            try c.play{value: msgValue}() {
                totalPaidIn += msgValue;
                // if the call succeeds, the contract either paid out jackpot (pot reset to 0) or not
                // bank may have received 1 wei fee when jackpot paid out
                uint256 currentBankBalance = c.bank().balance;
                uint256 bankDiff = currentBankBalance - initialBankBalance - totalBankFees;
                if (bankDiff > 0) {
                    totalBankFees += bankDiff;
                }
            } catch {
                // play() reverted; no state change
            }
        }
        uint256 pot = c.pot();
        // Invariant: pot cannot exceed total paid in minus fees taken by bank.
        // In the reference contract, the pot is occasionally reset to 0 (when random==0) and then grows again.
        // So pot <= totalPaidIn - totalBankFees always holds.
        // The buggy contract never resets pot, so after some calls totalPaidIn - totalBankFees grows
        // at a slower rate than pot, eventually breaking the inequality.
        assertTrue(pot <= totalPaidIn - totalBankFees);
    }
}

