pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        // warp to a known future timestamp so fuzz seed is reproducible
        vm.warp(1_700_000_000);
        vm.roll(1);
        c = new C();
    }

    function testFuzz_property(uint8 times) public {
        // times represents the number of play() calls; fuzzer searches for a counterexample
        // bind to a non-trivial domain that makes the bug observable but still wide
        times = uint8(bound(uint256(times), 2, 100));

        address actor = makeAddr("player");
        uint256 ticket = 10 ether;
        vm.deal(actor, ticket * times);

        vm.startPrank(actor);
        for (uint256 i = 0; i < times; i++) {
            c.play{value: ticket}();
        }
        vm.stopPrank();

        // General rule: the pot balance must be less than or equal to the amount that would
        // remain if the jackpot was never won and one fee was deducted (i.e. <= TICKET_AMOUNT times the
        // number of calls - FEE_AMOUNT). Since TICKET_AMOUNT * times is the total paid in,
        // a resetting contract (reference) never exceeds this because a win clears pot to 0;
        // the mutant (random=1) never resets, so after 2+ calls pot > TICKET_AMOUNT*times - FEE_AMOUNT.
        uint256 maxPossible = ticket * times - 1 ether;
        assertTrue(c.pot() <= maxPossible, "pot should not exceed max possible without reset");
    }
}

