import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint8 dummy) public {
        // Adversarial re-entrant caller that triggers play in its receive,
        // forcing a scenario where the jackpot should be paid out but the
        // adversarial receive can observe the state difference.
        Attacker attacker = new Attacker(c);
        vm.deal(address(attacker), 10 ether);
        vm.prank(address(attacker));
        attacker.triggerPlay();
        // After the re-entrant sequence, the pot in the reference contract
        // must be 0 (payout occurred) while the mutant keeps it non-zero.
        assertEq(uint256(attacker.potSnapshot()), 0);
    }
}

contract Attacker {
    C public target;
    uint256 public potSnapshot;
    bool private firstCall = true;
    constructor(C _target) { target = _target; }
    function triggerPlay() public payable {
        target.play{value: 10}();
        firstCall = false;
    }
    receive() external payable {
        if (firstCall) {
            // Re-enter with another play call to simulate a sequence
            // where the second call triggers a win (random == 0) and
            // then the attacker can observe the pot before the transfer.
            target.play{value: 10}();
        } else {
            // Capture the pot state after the winning payout (or lack thereof).
            potSnapshot = target.pot();
        }
    }
}

