pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint8 numPlays) public {
        // Bound to avoid overflow but keep wide enough to find bug
        numPlays = uint8(bound(numPlays, 1, 10));

        // Track total fees that should have been paid to the bank
        uint expectedBankFees = 0;

        // Perform the specified number of plays
        for (uint i = 0; i < numPlays; i++) {
            address player = address(uint160(uint(keccak256(abi.encodePacked(i)))));
            vm.deal(player, 10 ether);
            vm.prank(player);
            c.play{value: 10}();

            // In the reference contract, when random==0 (which happens ~50%), 
            // bank receives FEE_AMOUNT. But since we cannot observe random,
            // we observe the actual state changes.
        }

        // After all plays, if the contract ever paid out, pot was reset to 0
        // and bank received FEE_AMOUNT. The invariant:
        // address(c).balance == c.pot() + (fees actually sent to bank)
        // But fees sent to bank = address(bank).balance - initial bank balance
        // Since bank starts with 0, fees sent = address(c.bank()).balance
        uint bankBalance = c.bank().balance;

        // In reference: if at least one win occurred, pot may be 0 and bank has some fees
        // If no wins, pot = numPlays * 10, bank = 0
        // In bug: never pays out, pot = numPlays * 10, bank = 0
        // So both satisfy equality trivially when no wins occur.
        // But when a win occurs in reference, pot resets to 0, bank gets 1 wei,
        // while bug doesn't reset pot or pay bank.
        // The invariant: address(c).balance == c.pot() + bankBalance
        // This holds for reference (since when win occurs, pot=0, bank gets fee,
        // balance = pot + bankBalance). For bug, when win occurs, pot continues
        // to grow but bank never gets paid, so balance < pot + bankBalance.
        assertTrue(address(c).balance == c.pot() + bankBalance);
    }
}

