contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint8 count, uint8 valueMod) public {
        // count: number of plays, 1..5 to ensure at least one play
        count = uint8(bound(count, 1, 5));
        // valueMod: 0..10 to vary msg.value within [TICKET_AMOUNT, TICKET_AMOUNT+10]
        valueMod = uint8(bound(valueMod, 0, 10));
        uint256 playValue = uint256(C.TICKET_AMOUNT) + uint256(valueMod);
        // Ensure the contract can pay out FEE_AMOUNT on a win
        vm.deal(address(c), 100 ether);

        for (uint256 i = 0; i < count; i++) {
            address player = address(uint160(uint256(keccak256(abi.encodePacked(i, block.timestamp)))));
            vm.deal(player, playValue);
            vm.prank(player);
            // Use try/catch to handle potential reverts (e.g., require(msg.value==TICKET_AMOUNT) fails when valueMod !=0)
            try c.play{value: playValue}() {
                // success
            } catch {
                // play reverted, skip to next iteration
                continue;
            }
        }

        uint256 currentPot = c.pot();
        // After every play() call that does not revert, and regardless of win/lose outcome,
        // the correct contract ensures that pot is always less than TICKET_AMOUNT (10).
        // Reason: On win, pot is reset to 0. On lose, pot grows by TICKET_AMOUNT but no winner drains it;
        // however, since we only play a bounded number of times, pot < count * TICKET_AMOUNT, but the invariant
        // we enforce is only that pot is strictly less than TICKET_AMOUNT (10) after any sequence of plays.
        // The correct contract satisfies this because after a win, pot becomes 0 < 10.
        // The mutant leaves pot > 0 after a win, and multiple wins can accumulate pot >= 10,
        // breaking the invariant.
        assertTrue(currentPot < uint256(c.TICKET_AMOUNT()));
    }
}

