        for (uint256 i = 0; i < winCount; i++) {
            vm.warp(block.timestamp + 1);
            vm.roll(block.number + 1);
            vm.deal(player, 10 ether);
            vm.prank(player);
            c.play{value: 10}();
            plays++;
        }
        assertTrue(c.pot() < 20);
    }
}

