pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
    }

    function testFuzz_property(uint256 seed, uint8 count) public {
        // Bound count to a reasonable range (1-5) to limit gas while covering multiple plays
        count = uint8(bound(count, 1, 5));

        // Derive entropy from seed for reproducibility
        bytes memory entropy = abi.encodePacked(seed, count);

        // Simulate playing the lottery `count` times, tracking whether a win occurred
        bool won = false;
        for (uint256 i = 0; i < count; i++) {
            // We need to manipulate block.timestamp and block.difficulty to control the random outcome
            // Since we cannot directly control keccak256, we brute-force by warping and rolling until random == 0
            // to guarantee a win. This is only for the fuzzer to explore the state space.
            // We set a fixed warp/roll per iteration to simulate different randomness.
            vm.warp(block.timestamp + i + 1);
            vm.roll(block.number + i + 1);

            address player = address(uint160(uint256(keccak256(abi.encodePacked("player", entropy, i))) & type(uint160).max));
            vm.deal(player, 10 ether);
            vm.prank(player);

            // If we want to force a win occasionally, we can precompute the random. But since
            // the fuzzer controls seed and count, we just let it play naturally multiple times.
            // The invariant: if a win occurs (random==0), pot must become 0 after the call.
            // If no win, pot must be a multiple of TICKET_AMOUNT.
            c.play{value: 10}();

            // Check after each play: if pot == 0, a win just occurred. Record it.
            if (c.pot() == 0) {
                won = true;
            }
        }

        // After all plays, if a win occurred at some point, pot must be 0 at that point.
        // The mutant fails because after a win, pot is not reset to 0, so c.pot() != 0 after that call.
        // General rule: after any sequence of plays containing at least one win, the final pot is 0
        // if the last call was a win, or a multiple of TICKET_AMOUNT otherwise. But simpler:
        // The reference always resets pot to 0 on a win. To detect the bug, we just check that
        // if *any* play call resulted in a win (pot==0 observed after a call), then at that moment
        // the contract's internal pot was correctly reset. The mutant would have pot > 0 after a win,
        // so c.pot() would never be 0 after any call in the loop. Thus we assert:
        // If we ever observe pot == 0 after a play(), we know the contract behaves correctly (reference).
        // If after all plays pot is never 0, either we never hit a win (which is fine) or the mutant
        // hid a win. To make the fuzzer find a violating input, we need an input where the mutant
        // would have a win but pot > 0. This requires at least one win. We can bias the loop to
        // eventually hit a win by trying many `count` and many `seed` values. The fuzzer will
        // eventually find a seed+count where random==0 happens (by chance) and the mutant fails.
        // To make the test pass on reference for ALL inputs, the assertion must be something that
        // holds true even if no win occurs. So we state: after the loop, if pot == 0, then a win
        // definitely occurred and pot was reset (true for ref). If pot > 0 and we never observed
        // a win (pot==0), then the reference is still fine. The mutant will sometimes have pot > 0
        // AFTER a win call, meaning pot was never 0 despite a win. We detect that by checking
        // if the contract's pot is non-zero even though a win should have occurred in some iteration.
        // To test that, we need to know if a win occurred. We can track by checking pot immediately
        // after each call; if pot == 0, we mark won = true. At the end, we assert: if won, then pot == 0.
        // For the reference, that's always true. For the mutant, if won is set, pot may still be >0.
        assertTrue(!won || c.pot() == 0, "after any win, pot must be 0");
    }
}

