pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint248 amount, address actor) public {
        vm.assume(actor != address(0) && actor != address(c) && actor != address(this));
        vm.assume(amount >= 10 && amount <= address(c).balance / 10);
        vm.deal(actor, amount * 10);
        vm.prank(actor);
        // deploy adversarial reverting receiver and pass it as msg.sender equivalent? No, actor is msg.sender.
        // The bug manifests when transfer to msg.sender fails; if msg.sender is a contract that reverts on receive.
        // We need an adversarial counterparty: a contract that reverts in its receive function.
        AdversarialReceiver adv = new AdversarialReceiver();
        // Transfer funds to adv to allow it to call play as msg.sender.
        vm.deal(address(adv), 10 ether);
        // Use prank to make adv the msg.sender.
        vm.prank(address(adv));
        // Call play multiple times to accumulate pot.
        // Since random is deterministic in test environment, we can just call once.
        // But we need to ensure the random condition triggers the win path (random==0).
        // We'll roll block number to manipulate randomness, but fuzzer will find triggering input.
        // For simplicity, we just call once; if random==0, winner gets pot transfer; if adv reverts on receive, pot is zeroed but transfer failed.
        c.play{value: 10}();
        // After play, contract balance should equal pot.
        assertEq(address(c).balance, c.pot());
    }
}

contract AdversarialReceiver {
    fallback() external payable {
        revert("revert on receive to break transfer");
    }
}
